package dev.multiserverzh;
import com.google.gson.*;
import java.util.*;
/** Seven-platform releases, legacy migration and platform-specific latest selection. */
public final class UniversalReleaseTest {
    private static int checks;
    private static final List<String> VERSIONS=List.of("1.20.4","1.21.11","26.1","26.1.1","26.1.2","26.2","26.3");
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static JsonObject release(String version,List<String> platforms,boolean alias){
        JsonObject r=new JsonObject();r.addProperty("tag_name","v"+version);r.addProperty("draft",false);r.addProperty("prerelease",false);
        JsonArray assets=new JsonArray();
        for(String platform:platforms)assets.add(asset(version,ModRelease.assetName(version,platform)));
        if(alias)assets.add(asset(version,"multiserverzh-"+version+".jar"));
        r.add("assets",assets);return r;
    }
    private static JsonObject asset(String version,String name){
        JsonObject a=new JsonObject();a.addProperty("name",name);a.addProperty("size",1234);a.addProperty("digest","sha256:"+"a".repeat(64));
        a.addProperty("browser_download_url","https://github.com/"+ModRelease.REPO+"/releases/download/v"+version+"/"+name);return a;
    }
    private static void reject(String json,String platform){
        try{ModRelease.parseLatest(json,platform);throw new AssertionError("Invalid release accepted for "+platform);}catch(java.io.IOException expected){checks++;}
    }
    public static void main(String[] args)throws Exception{
        JsonObject all=release("0.6.0",VERSIONS,true);
        for(String platform:VERSIONS){
            var result=ModRelease.parse(all.toString(),platform);
            check(result.url().getPath().endsWith("-mc"+platform+".jar"),"exact platform wins over alias");
            check(ModRelease.newer(result.version(),"0.5.46"),"upgrade from local hotfix");
            JsonArray releases=new JsonArray();releases.add(release("0.7.0",List.of("26.3"),false));releases.add(all);
            JsonObject draft=release("9.0.0",VERSIONS,true);draft.addProperty("draft",true);releases.add(draft);
            JsonObject preview=release("8.0.0",VERSIONS,true);preview.addProperty("prerelease",true);releases.add(preview);
            check(ModRelease.parseLatest(releases.toString(),platform).version().equals(platform.equals("26.3")?"0.7.0":"0.6.0"),"latest supported release skips unrelated/draft/prerelease");
            JsonArray unordered=new JsonArray();unordered.add(all);unordered.add(release("0.5.42",VERSIONS,true));
            check(ModRelease.parseLatest(unordered.toString(),platform).version().equals("0.6.0"),"numeric version beats publication order");
            JsonObject broken=release("0.6.1",List.of(platform),false);broken.getAsJsonArray("assets").get(0).getAsJsonObject().addProperty("digest","md5:abcd");
            reject("["+broken+"]",platform);
            JsonObject wrong=release("0.6.1",List.of(platform),false);wrong.getAsJsonArray("assets").get(0).getAsJsonObject().addProperty("browser_download_url","https://evil.example/mod.jar");
            reject("["+wrong+"]",platform);
        }
        JsonObject legacy=release("0.6.0",List.of(),true);
        check(ModRelease.parse(legacy.toString(),"1.21.11").url().getPath().endsWith("/multiserverzh-0.6.0.jar"),"legacy 1.21.11 alias");
        for(String platform:VERSIONS)if(!platform.equals("1.21.11"))reject("["+legacy+"]",platform);
        check(ModRelease.newer("0.6","0.5.46"),"two-component version accepted");
        check(!ModRelease.newer("0.6.0","0.6"),"equivalent zero patch");
        check(ModRelease.newer("0.6.1","0.6"),"upgrade after zero patch");
        check(!ModRelease.newer("0.6-beta","0.5.46"),"no prerelease");
        reject("[]","26.2");reject("["+all+"]","26.2-rc1");
        System.out.println("Passed "+checks+" universal release checks across seven Minecraft versions");
    }
}

