package dev.multiserverzh;
import java.nio.file.*;
import java.util.*;
/** Probe a real GitHub release response using either old or current updater code. */
public final class ReleaseProbe {
    public static void main(String[] args)throws Exception {
        String json=Files.readString(Path.of(args[0])),mc=args[1],mode=args[2];
        ModRelease.Release selected;
        if(mode.equals("legacy"))selected=ModRelease.parse(json);
        else selected=ModRelease.parseLatest("["+json+"]",mc);
        if(!selected.version().equals("0.6.0"))throw new AssertionError("Wrong release "+selected.version());
        String suffix=mode.equals("legacy")&&mc.equals("1.21.11")?"/multiserverzh-0.6.0.jar":"-mc"+mc+".jar";
        if(!selected.url().getPath().endsWith(suffix))throw new AssertionError("Wrong platform asset: "+selected.url());
        System.out.println("RELEASE_PROBE_OK "+mode+" "+mc+" "+selected.url());
    }
}
